bool blocksOverlap(List<SleepBlock> blocks) {
  final s = [...blocks]..sort((a, b) => a.start.compareTo(b.start));
  for (var i = 1; i < s.length; i++) {
    if (s[i].start < s[i - 1].end) return true;
  }
  return false;
}

