  if (m % 60 == 0) return HapticTier.hour;
  if (m % 30 == 0) return HapticTier.thirty;
  if (m % 10 == 0) return HapticTier.ten;
  if (m % 5 == 0) return HapticTier.five;
  return HapticTier.minute;
}

