        h.poster.mode = FakePoster.Mode.OK
        val next = h.coordinator.onArrival(item("J", timestamp = 200), HIGH)

        assertThat(next).isEqualTo(Delivered("J"))
        assertThat(h.budget.state.spentPoints).isEqualTo(2)
    }

